<template><div class="main-content"><breadcumb page="Configuración de WhatsApp" folder="WhatsApp" /><div v-if="isLoading" class="loading_page spinner spinner-primary mr-3"></div><div v-if="!isLoading"><b-alert variant="warning" :show="!globallyEnabled">WhatsApp está desactivado actualmente por el administrador de la plataforma. Puedes configurar tu cuenta, pero los mensajes no se enviarán hasta que se habilite.</b-alert><b-row><b-col md="8"><b-card title="Conexión" class="mb-4"><b-row><b-col md="12" class="mb-3"><label class="font-weight-bold">Proveedor</label><b-form-input value="Meta Cloud API" disabled /></b-col><b-col md="6" class="mb-3"><label class="font-weight-bold">ID del número de teléfono</label><b-form-input v-model="form.phone_number_id" placeholder="Ej.: 123456789012345" /></b-col><b-col md="6" class="mb-3"><label class="font-weight-bold">ID de la cuenta de WhatsApp Business</label><b-form-input v-model="form.business_account_id" placeholder="Opcional" /></b-col><b-col md="12" class="mb-3"><label class="font-weight-bold">Token de acceso</label><b-form-input v-model="form.access_token" type="password" :placeholder="status.has_access_token?'••••••••  (dejar vacío para conservar)':'Token de acceso permanente'" autocomplete="new-password" /></b-col><b-col md="6" class="mb-3"><label class="font-weight-bold">Secreto de la aplicación</label><b-form-input v-model="form.app_secret" type="password" :placeholder="status.has_app_secret?'••••••••  (dejar vacío para conservar)':'Para firma del webhook (opcional)'" autocomplete="new-password" /></b-col><b-col md="6" class="mb-3"><label class="font-weight-bold">Token de verificación del webhook</label><b-form-input v-model="form.webhook_verify_token" placeholder="Cualquier cadena secreta que configures en Meta" /></b-col><b-col md="6" class="mb-3"><label class="font-weight-bold">Código de país predeterminado</label><b-form-input v-model="form.default_country_code" placeholder="Ej.: 504" /><small class="text-muted">Se antepone a números locales cuando corresponde.</small></b-col></b-row><div class="mt-2"><b-button variant="primary" @click="save" :disabled="saving"><lucide-icon name="check" /> Guardar</b-button><b-button variant="outline-success" class="ml-2" @click="testConnection" :disabled="testing||saving"><lucide-icon name="power" /> {{testing?'Probando...':'Probar conexión'}}</b-button></div></b-card><b-card title="Mensajes automáticos" class="mb-4"><p class="text-muted">Envía automáticamente un mensaje de WhatsApp cuando ocurren estos eventos. Cada evento utiliza la plantilla correspondiente según su clave.</p><b-form-checkbox v-for="key in automationKeys" :key="key" v-model="form.automations[key]" switch class="mb-2">{{automationLabels[key]||key}}</b-form-checkbox></b-card></b-col><b-col md="4"><b-card class="mb-4"><div class="text-center"><h5>Estado de la conexión</h5><b-badge :variant="status.is_connected?'success':'secondary'" class="px-3 py-2" style="font-size:.9rem">{{status.is_connected?'Conectado':'No conectado'}}</b-badge><p v-if="status.connected_at" class="text-muted mt-2 mb-0"><small>Desde {{status.connected_at}}</small></p></div></b-card><b-card title="Cuota mensual" class="mb-4"><div class="d-flex justify-content-between"><span>Usados</span><strong>{{quota.used}}</strong></div><div class="d-flex justify-content-between"><span>Límite</span><strong>{{quota.max===null?'Ilimitado':quota.max}}</strong></div><div class="d-flex justify-content-between" v-if="quota.remaining!==null"><span>Restantes</span><strong>{{quota.remaining}}</strong></div><b-progress v-if="quota.max" :max="quota.max" class="mt-2"><b-progress-bar :value="quota.used" :variant="quotaVariant"></b-progress-bar></b-progress></b-card><b-card title="URL del webhook"><p class="text-muted mb-1"><small>Pega esta URL en la configuración de webhook de tu aplicación de Meta:</small></p><b-form-textarea :value="webhookUrl" readonly rows="2" size="sm" /></b-card></b-col></b-row></div></div></template>
<script>export default{data(){return{isLoading:true,saving:false,testing:false,globallyEnabled:false,webhookUrl:'',automationKeys:[],automationLabels:{invoice_created:'Factura creada (nueva venta)',payment_received:'Pago recibido'},status:{is_connected:false,connected_at:null,has_access_token:false,has_app_secret:false},quota:{used:0,max:null,remaining:null},form:{phone_number_id:'',business_account_id:'',access_token:'',app_secret:'',webhook_verify_token:'',default_country_code:'',automations:{}}}},computed:{quotaVariant(){if(!this.quota.max)return'success';const pct=this.quota.used/this.quota.max*100;if(pct>=100)return'danger';if(pct>=80)return'warning';return'success'}},mounted(){this.load()},methods:{makeToast(variant,msg,title){this.$root.$bvToast.toast(msg,{title,variant,solid:true})},load(){this.isLoading=true;axios.get('/whatsapp/settings').then(res=>{const d=res.data;this.globallyEnabled=d.globally_enabled;this.webhookUrl=d.webhook_url;this.automationKeys=d.automation_keys||[];this.status=d.settings;this.quota=d.quota;this.form.phone_number_id=d.settings.phone_number_id||'';this.form.business_account_id=d.settings.business_account_id||'';this.form.webhook_verify_token=d.settings.webhook_verify_token||'';this.form.default_country_code=d.settings.default_country_code||'';this.form.automations=Object.assign({},d.settings.automations||{})}).catch(()=>this.makeToast('danger','No se pudo cargar la configuración de WhatsApp.','Error')).finally(()=>this.isLoading=false)},save(){this.saving=true;axios.post('/whatsapp/settings',this.form).then(()=>{this.makeToast('success','Configuración de WhatsApp guardada.','Éxito');this.form.access_token='';this.form.app_secret='';this.load()}).catch(err=>{const msg=err.response?.data?.message||'No se pudo guardar.';this.makeToast('danger',msg,'Error')}).finally(()=>this.saving=false)},testConnection(){this.testing=true;axios.post('/whatsapp/settings',this.form).then(()=>axios.post('/whatsapp/test')).then(res=>{this.makeToast(res.data.status==='success'?'success':'danger',res.data.message,res.data.status==='success'?'Éxito':'Falló');this.form.access_token='';this.form.app_secret='';this.load()}).catch(err=>{const msg=err.response?.data?.message||'La prueba de conexión falló.';this.makeToast('danger',msg,'Falló')}).finally(()=>this.testing=false)}}}</script>